from lib import *
R=[]
R.append((3151182,"चेडर और सेज के नमकीन स्कोन","कुछ नाश्तों की तुलना में अधिक प्रोटीन वाले ये स्कोन डायलिसिस के दौरान एक अच्छा व्यंजन हो सकते हैं।","8",None,
["350g सादा मैदा","1 छोटा चम्मच क्रीम ऑफ़ टार्टर","½ छोटा चम्मच बाइकार्बोनेट ऑफ़ सोडा (बेकिंग सोडा)","50g बिना नमक का मक्खन","100g चेडर, कद्दूकस किया हुआ","1 छोटा चम्मच सूखा सेज","1 अंडा, फेंटा हुआ","250ml ऑर्गेनिक सोया दूध"],
["ओवन को 190°C/ 170°C फ़ैन/ गैस मार्क 5 पर गरम करें। बेकिंग ट्रे पर कागज़ बिछाएँ। एक कटोरे में मैदा, क्रीम ऑफ़ टार्टर और बेकिंग सोडा मिलाएँ, फिर मक्खन को उँगलियों से तब तक मिलाएँ जब तक वह बारीक ब्रेड क्रम्ब्स जैसा न दिखने लगे।","80g कद्दूकस किया हुआ चेडर और सूखा सेज मिलाएँ। बीच में गड्ढा बनाएँ और दूध डालें। चाकू को काटने की गति में चलाते हुए आटा गूँध लें।","अपनी कार्य-सतह और हाथों पर मैदा छिड़कें, आटा निकालें और चिकना होने तक गूँधें, फिर लगभग 3cm मोटा गोल आकार दें। इसे बेकिंग ट्रे पर रखें और 8 फाँकों में निशान लगाएँ। ऊपर फेंटा हुआ अंडा लगाएँ और बचा हुआ 20g चेडर छिड़कें।","सुनहरा होने तक 20 मिनट पकाएँ। थोड़े मक्खन के साथ गरमागरम परोसना सबसे अच्छा रहता है।"],
[[CH,"सूप के साथ ब्रेड रोल की जगह एक स्वादिष्ट नमकीन विकल्प, या इसे अपने पैक किए लंच में खाएँ।"],[CB,"इन स्कोन में कार्बोहाइड्रेट का मुख्य स्रोत मैदा है, कार्बोहाइड्रेट के मान उन लोगों के लिए शामिल किए गए हैं जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],[PP,"क्रीम ऑफ़ टार्टर पोटैशियम का स्रोत है लेकिन बेकिंग पाउडर की तुलना में फ़ॉस्फ़ेट में कम है। उपयोग की गई मात्रा इस रेसिपी को कम पोटैशियम वाले आहार में कभी-कभार के नाश्ते के रूप में उपयोग करने की अनुमति देती है।\nऑर्गेनिक सोया दूध में गाय के दूध की तुलना में फ़ॉस्फ़ेट और पोटैशियम कम होता है, इसलिए फ़ॉस्फ़ेट और पोटैशियम की मात्रा कम करने के लिए यहाँ इसका उपयोग किया गया है।\nचीज़ और बेक्ड चीज़ों में अक्सर फ़ॉस्फ़ेट अधिक होता है, इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो कृपया इस नाश्ते के साथ उसे लें।"],[PR,"स्कोन की सामग्री (दूध, अंडा और चेडर) का अर्थ है कि वे कम प्रोटीन वाला आहार लेने वाले व्यक्ति के लिए उपयुक्त नहीं होंगे।"],[GF,"ग्लूटेन-मुक्त आटे का उपयोग करें।"],[HO,"साबुत गेहूँ का आटा और कम वसा वाला चीज़ उपयोग करें।"],[ST,"हवाबंद डिब्बे में फ्रिज में तीन दिन तक रहेंगे।"]],
[]))
R.append((3154406,"बटरनट स्क्वैश और बकरी के चीज़ के पार्सल","इस व्यंजन में सब्ज़ियों को उबालने से पोटैशियम कम करने में मदद मिलती है, लेकिन बकरी का चीज़ मिलाने से फिर भी भरपूर स्वाद रहता है।","4",None,
["1 शीट बेली हुई तैयार पफ़ पेस्ट्री","1 बटरनट स्क्वैश, छिला और टुकड़ों में कटा हुआ","1 बड़ा शकरकंद, छिला और टुकड़ों में कटा हुआ","1 छोटा प्याज़, कटा हुआ","5g तिल या कलौंजी","1 छोटा चम्मच जैतून का तेल","60g मुलायम बकरी का चीज़","1 अंडा, फेंटा हुआ","चुटकी भर पिसी काली मिर्च",["परोसने के लिए","240g लेट्यूस, कटा हुआ"],["परोसने के लिए","80g खीरा, कटा हुआ"]],
["ओवन को 180°c/ 160°c फ़ैन/ गैस मार्क 4 पर पहले से गरम करें। शकरकंद और बटरनट स्क्वैश को सॉसपैन में रखें, पानी से ढकें और उबालें, नरम होने तक पकाएँ।","शकरकंद और बटरनट स्क्वैश का पानी निथारें और उन्हें कटे हुए प्याज़ के साथ रोस्टिंग ट्रे में डालें। ऊपर से जैतून का तेल डालें, काली मिर्च छिड़कें और 20 मिनट बेक करें। ओवन से निकालें और ठंडा करें।","पेस्ट्री को 8 बराबर आयतों में काटें। 4 आयतों को कागज़ बिछी बेकिंग ट्रे पर रखें और हर आयत के बीच में सब्ज़ी के मिश्रण का ¼ भाग चम्मच से रखें, चारों किनारों पर जगह छोड़ें। हर सब्ज़ी के मिश्रण पर 15g चूरा किया हुआ बकरी का चीज़ डालें। पेस्ट्री के किनारों पर चारों ओर थोड़ा फेंटा हुआ अंडा लगाएँ।","अपने बाकी 4 आयत लें, उन्हें लंबाई में ढीले ढंग से आधा मोड़ें और दोनों परतों में 5 चीरे लगाएँ, किनारा छोड़कर। खोलें और 4 पार्सलों के ऊपर रखें, किनारों को नीचे की परत के अंडा लगे किनारों पर दबाकर पार्सल को बंद करें।","ऊपर अंडा लगाएँ और तिल या कलौंजी छिड़कें और सुनहरा होने तक 25 मिनट पकाएँ। पक जाने पर, ओवन से निकालें।","पक जाने पर, ओवन से निकालें और हरे सलाद के साथ परोसें।"],
[[CH,"एक स्वादिष्ट व्यंजन जो जल्दी और आसानी से तैयार हो जाता है।"],[CB,"इस भोजन में कार्बोहाइड्रेट के मुख्य स्रोत शकरकंद, बटरनट स्क्वैश और पेस्ट्री हैं। कार्बोहाइड्रेट के मान उन लोगों के लिए दिए गए हैं जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],[PP,"पोटैशियम की मात्रा कम करने के लिए हमने बटरनट स्क्वैश और शकरकंद को बेक करने की बजाय उबाला है।\nइस व्यंजन में फ़ॉस्फ़ेट देने के लिए केवल थोड़ा सा मुलायम चीज़ है और इसलिए कुल फ़ॉस्फ़ेट की मात्रा कम है।"],[PR,"इस व्यंजन में प्रोटीन कम है; प्रोटीन बढ़ाने के लिए आप चीज़ को दोगुना करने पर विचार कर सकते हैं, फिर भी भोजन में पोटैशियम और फ़ॉस्फ़ेट कम रहेगा।"],[GF,"ग्लूटेन-मुक्त पेस्ट्री का उपयोग करें।"],[VG,"वीगन चीज़ का उपयोग करें।"],[HO,"पेस्ट्री में वसा अधिक होती है; अधिक सेहतमंद विकल्प के लिए आप पेस्ट्री की ऊपरी परत छोड़कर खुला पार्सल बना सकते हैं।"],[TP,"यदि आपको घर पर बटरनट स्क्वैश और शकरकंद छीलना कठिन लगता है, तो ये अधिकांश सुपरमार्केट के फ़्रीज़र सेक्शन में पहले से तैयार मिलते हैं।"]],
[]))
R.append((3162079,"चिकन सीज़र रैप","एक स्वादिष्ट उच्च प्रोटीन रैप, जो किडनी और लंचबॉक्स के अनुकूल है। यह पोटैशियम और फ़ॉस्फ़ेट में भी कम है, इसलिए डायलिसिस पर ले जाने के लिए आदर्श है।","4",None,
["175g पका हुआ चिकन","50g मेयोनेज़","1 लहसुन की कली, कुचली हुई","50g परमेसन चीज़ का टुकड़ा","100g आइसबर्ग लेट्यूस, मोटा कटा हुआ","¼ छोटा चम्मच वूस्टरशायर सॉस","काली मिर्च","4 मुलायम टॉर्टिला"],
["पके हुए चिकन को पट्टियों में चीरें और कटी हुई लेट्यूस की पत्तियों और कुचले हुए लहसुन के साथ कटोरे में डालें।","परमेसन के पतले स्लाइस कटोरे में छीलकर डालें, फिर मेयोनेज़ और वूस्टरशायर सॉस डालें और धीरे से मिलाएँ, काली मिर्च से स्वाद दें।","रैप बनाने के लिए, मिश्रण का ¼ भाग टॉर्टिला के निचले आधे हिस्से पर चम्मच से रखें। टॉर्टिला के निचले हिस्से को ऊपर की ओर भरावन के ऊपर मोड़ें।","दोनों तरफ़ दो-दो मोड़ दें और कसकर लपेट लें। बाकी तीन टॉर्टिला के साथ दोहराएँ। इसे पूरा खाएँ या आधा काटकर तुरंत परोसें, या जब तक खाना न हो पूरा रखने के लिए फ़ॉइल में लपेट लें।"],
[[CH,"पारंपरिक सीज़र सलाद को रैप में बदला गया है, जो एकदम सही झटपट दोपहर का भोजन या हल्का रात का खाना है।"],[CB,"इस व्यंजन में कार्बोहाइड्रेट का मुख्य स्रोत टॉर्टिला रैप है। इस व्यंजन का कार्बोहाइड्रेट मान उन लोगों के लिए दिया गया है जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],[PP,"यदि आप इस रेसिपी में दिए गए परोसे के आकार का पालन करते हैं, तो यह व्यंजन पोटैशियम और फ़ॉस्फ़ेट दोनों में कम है। चिकन और परमेसन चीज़ दोनों में फ़ॉस्फ़ेट होता है, लेकिन इस रेसिपी में उपयोग की गई थोड़ी मात्रा कुल फ़ॉस्फ़ेट को कम रखती है। यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो उन्हें इस व्यंजन के साथ लेना सुनिश्चित करें।"],[PR,"इस रेसिपी में उपयोग किए गए चिकन और चीज़ प्रोटीन का स्रोत हैं, जो डायलिसिस ले रहे लोगों और अधिक प्रोटीन खाने की ज़रूरत वाले किसी भी व्यक्ति के लिए बहुत अच्छा है।"],[GF,"ग्लूटेन-मुक्त टॉर्टिला रैप का उपयोग करें।"],[VT,"इसके बजाय मांस-रहित चिकन-जैसे टुकड़े या छोले उपयोग करें। जाँच लें कि आपका परमेसन चीज़ शाकाहारियों के लिए उपयुक्त है।"],[VG,"इसके बजाय मांस-रहित चिकन-जैसे टुकड़े या छोले उपयोग करें। उपयुक्त डेयरी-मुक्त मेयोनेज़ और डेयरी-मुक्त कठोर इतालवी शैली का चीज़ उपयोग करें।"],[HO,"इस रेसिपी में कोई अतिरिक्त नमक नहीं है। परमेसन चीज़, वूस्टरशायर सॉस, मेयोनेज़ और टॉर्टिला रैप में नमक होता है, जिससे यह रेसिपी कम नमक वाले व्यंजन की श्रेणी की सीमा से थोड़ी ऊपर है। नमक की मात्रा कम करने के लिए, सबसे कम नमक वाले रैप चुनें। बहुत ज़्यादा डालने से बचने के लिए वूस्टरशायर सॉस, मेयोनेज़ और परमेसन चीज़ को माप लें। नमक की मात्रा और भी कम करने के लिए, आप वूस्टरशायर सॉस की जगह एक छोटा चम्मच नींबू का रस और मेयोनेज़ की जगह कुछ सादा दही उपयोग करने पर विचार कर सकते हैं।\nयदि आप इस व्यंजन में वसा कम करना चाहते हैं, तो लाइट मेयोनेज़ चुनें।\nसाबुत गेहूँ के रैप का उपयोग करने से आपके आहार में फ़ाइबर बढ़ेगा।"],[ST,"बन जाने के बाद, इसे फ्रिज में रखें और दो दिन के भीतर उपयोग करें। लंच के लिए पैक करते समय, इसे ठंडा रखने के लिए कूल पैक का उपयोग करने की सलाह दी जाती है।"],[TP,"यदि आपको चार परोसे नहीं चाहिए, तो आप रेसिपी की मात्रा घटा सकते हैं।"]],
[]))
R.append((3194515,"फलियों और कूसकूस का सलाद","कम प्रोटीन वाला व्यंजन जो तैयार करने में आसान है। यह दोपहर के भोजन के लिए बढ़िया है और पोटैशियम, फ़ॉस्फ़ेट और नमक में कम है।","2",None,
["1 बड़ा चम्मच जैतून का तेल","1 लाल प्याज़, बारीक कटा हुआ","150g कूसकूस","240ml कम नमक वाला सब्ज़ी स्टॉक","1 लाल शिमला मिर्च, 1cm के टुकड़ों में कटी हुई","400g डिब्बाबंद तीन फलियों का सलाद, पानी में","10g ताज़ा अजमोद (पार्सले), कटा हुआ (वैकल्पिक)"],
["प्याज़ और शिमला मिर्च काटकर एक तरफ़ रख दें।","सब्ज़ी का स्टॉक बनाएँ और कूसकूस को माप लें। गरम सब्ज़ी स्टॉक को कूसकूस में चलाएँ, ढक दें और पाँच मिनट रहने दें।","एक छोटे बर्तन में जैतून का तेल गरम करें। प्याज़ को धीमी आँच पर पाँच मिनट या नरम होने तक भूनें, फिर बर्तन को आँच से उतार लें।","कूसकूस से ढक्कन हटाएँ और काँटे से उसे फुला लें। पका हुआ प्याज़ और ताज़ी शिमला मिर्च डालें, फिर फलियों के सलाद का पानी निथारकर कूसकूस में डालें। अच्छी तरह मिलने तक धीरे से चलाएँ। यदि अजमोद का उपयोग कर रहे हैं, तो परोसने से पहले उसे सलाद पर छिड़कें।"],
[[CH,"फलियों और कूसकूस का एक आसान वीगन सलाद जिसे सेहतमंद लंच के लिए पहले से तैयार किया जा सकता है।"],[CB,"इस व्यंजन में कार्बोहाइड्रेट के मुख्य स्रोत कूसकूस और फलियाँ हैं। इस व्यंजन का कार्बोहाइड्रेट मान उन लोगों के लिए दिया गया है जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],[PP,"फलियों में पोटैशियम और फ़ॉस्फ़ेट होता है, लेकिन इस रेसिपी में दी गई मात्रा का उपयोग करने पर कुल स्तर कम रहते हैं। यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो उन्हें इस व्यंजन के साथ लेना सुनिश्चित करें।"],[PR,"इस रेसिपी में प्रोटीन कम है, जो उन लोगों के लिए बहुत अच्छा है जिन्हें प्रोटीन घटाने की सलाह दी गई है। यदि आपको प्रोटीन बढ़ाने की सलाह दी गई है, तो आप टूना का एक छोटा डिब्बा मिला सकते हैं। स्प्रिंग वाटर में टूना ढूँढें और उपयोग से पहले पानी निथार लें।"],[GF,"ग्लूटेन-मुक्त विकल्प के लिए बकव्हीट या क्विनोआ और ग्लूटेन-मुक्त सब्ज़ी स्टॉक का उपयोग करें।"],[ST,"यह व्यंजन अच्छी तरह टिकता है और फ्रिज में 3 दिन तक रखा जा सकता है।"]],
[]))
R.append((3204614,"नारियल चावल के साथ कैरिबियाई मिर्च वाले झींगे",">","4",None,
["450g झींगे (कच्चे या पके हुए)","थोड़ी पिसी काली मिर्च","1 बड़ा चम्मच कॉर्नफ़्लोर","2 तीखी लाल मिर्चें, बारीक कटी हुई","1 गुच्छा हरे प्याज़ (सफ़ेद और हरा भाग), बारीक कटा हुआ","1 बड़ा चम्मच वनस्पति तेल","3 लहसुन की कलियाँ, कीमा की हुई","240g लंबे दाने वाले चावल, धुले हुए","400ml डिब्बाबंद नारियल का दूध","1 बड़ा चम्मच नारियल का तेल","30g ताज़ा धनिया, मोटा कटा हुआ",["परोसने के लिए साइड सलाद","80g लेट्यूस, मोटा फाड़ा हुआ"],["परोसने के लिए साइड सलाद","50g खीरा, कटा हुआ"],["परोसने के लिए साइड सलाद","2 टमाटर, कटे हुए"],["परोसने के लिए साइड सलाद","1 शिमला मिर्च, कटी हुई"],["परोसने के लिए साइड सलाद","कम नमक वाली सलाद ड्रेसिंग"]],
["चावल तैयार करने के लिए नारियल का दूध और नारियल का तेल एक बर्तन में डालें और उबालें। चावल डालें, दोबारा उबाल आने दें, फिर आँच धीमी करें और बर्तन पर ढक्कन लगा दें। चावल को तब तक पकाएँ जब तक सारा तरल सोख न लिया जाए। आँच से उतारें और कुछ मिनट रहने दें।","जब चावल पक रहे हों, तब झींगों को कॉर्नफ़्लोर, काली मिर्च, पैपरिका और मिर्च के फ़्लेक्स के साथ मिलाएँ। एक बर्तन में आधा तेल मध्यम आँच पर गरम करें और झींगे तलें – यदि पके हुए झींगे हैं तो केवल दोबारा गरम करने के लिए थोड़ी देर; यदि कच्चे झींगे हैं तो अच्छी तरह पकने तक अधिक देर।","एक अलग बर्तन में बचा हुआ तेल मध्यम/धीमी आँच पर गरम करें और मिर्चें, हरे प्याज़ (केवल सफ़ेद भाग) और लहसुन को लगभग 3 मिनट पकाएँ। पके हुए झींगे हरे प्याज़ के हरे भागों के साथ डालें और सब कुछ उछालकर मिला दें। झींगे पहले ही पक चुके हैं इसलिए यह बस जल्दी से मिलाना है।","लेट्यूस, खीरा, टमाटर और शिमला मिर्च को मिलाकर साइड सलाद तैयार करें और अपनी पसंदीदा सलाद ड्रेसिंग से स्वाद दें।","झींगों को नारियल चावल के ऊपर परोसें, ऊपर से ताज़ा धनिया छिड़कें और साथ में सलाद रखें।"],
[[CH,"झटपट और आसानी से बनने वाला झींगे का व्यंजन जो फ़ॉस्फ़ेट, पोटैशियम और नमक में कम है।"],[CB,"चावल कार्बोहाइड्रेट का मुख्य स्रोत है, और यह मान उन लोगों के लिए दिया गया है जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],["फ़ॉस्फ़ेट/पोटैशियम","दी गई मात्रा और परोसे के आकार का पालन करने पर यह रेसिपी पोटैशियम में कम है, इसलिए यह उपयुक्त है यदि आपको अपने आहार में पोटैशियम की मात्रा घटाने की सलाह दी गई है। यह फ़ॉस्फ़ेट में भी कम है, लेकिन इसमें कुछ फ़ॉस्फ़ेट होता है, जो मुख्य रूप से झींगों से आता है, इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो निर्देशानुसार लें।"],[PR,"यह रेसिपी प्रोटीन का स्रोत है। यदि आपको अधिक प्रोटीन खाने की सलाह दी गई है, तो दिन के अन्य भोजनों में अतिरिक्त प्रोटीन लेने पर विचार करें।"],["खाद्य सुरक्षा","यदि आप कच्चे झींगों का उपयोग कर रहे हैं, तो संक्रमण के जोखिम से बचने के लिए सुनिश्चित करें कि वे पूरी तरह पके हों।"],["परोसने का सुझाव","इस व्यंजन को ताज़ा बना हुआ खाना सबसे अच्छा रहता है।"],[HO,"यदि आप इस व्यंजन को कम वसा वाला बनाना चाहते हैं, तो लाइट/कम वसा वाले नारियल के दूध का उपयोग करने पर विचार करें।"]],
[]))
R.append((3227420,"एशियाई स्टिकी चिकन सलाद",">","2",None,
["150g कच्चा चिकन ब्रेस्ट मांस","1 लहसुन की कली, कुचली हुई","1 बड़ा चम्मच कम नमक वाली सोया सॉस","1 बड़ा चम्मच शहद या मेपल सिरप","150g सफ़ेद पत्तागोभी, बारीक कतरी हुई","1 बड़ा चम्मच तिल का तेल","2 गाजर, छिली और बारीक कतरी हुई","3 हरे प्याज़, लंबाई में बारीक कटे हुए","¼ खीरा, बारीक लंबे टुकड़ों में कटा हुआ","मुट्ठी भर पुदीने की पत्तियाँ","40g बिना नमक के सादे बादाम या मूँगफली, मोटे कटे हुए","1 बड़ा चम्मच तिल, भुने हुए","100g सूखे राइस नूडल्स"],
["चिकन ब्रेस्ट को क्लिंग फ़िल्म के बीच रखें और बेलन से तब तक कूटें जब तक वह चपटा न हो जाए। चिकन को पट्टियों में काटें।","सोया सॉस, शहद, लहसुन और आधा तिल का तेल एक कटोरे में डालें और मिलाने के लिए फेंटें। चिकन को मैरिनेड में डालें, अच्छी तरह मिलाएँ, ढक दें और कम से कम 20 मिनट ठंडा करें।","एक फ्राइंग पैन में बचा हुआ तिल का तेल मध्यम/तेज़ आँच पर गरम करें, फिर चिकन की पट्टियाँ डालें और पूरी तरह पकने तक तलें। चिकन को पैन से निकालें और प्लेट में एक तरफ़ रख दें।","आँच धीमी करें और बचा हुआ मैरिनेड मिश्रण डालें और लगभग 5 मिनट तक चिपचिपी ड्रेसिंग बनने तक पकाएँ। ठंडा होने दें।","केतली भर पानी उबालें और उबलता पानी एक कटोरे में डालें। नूडल्स को पानी में डालें और 3 मिनट रहने दें। पानी निथार लें।","बाकी सामग्री को एक कटोरे में डालें और धीरे से चिकन और नूडल्स मिलाएँ। ऊपर से ड्रेसिंग डालकर परोसें।"],
[[CH,"स्वादिष्ट एशियाई शैली का सलाद, जो नमक, पोटैशियम और फ़ॉस्फ़ेट में कम है।"],[CB,"इस रेसिपी में राइस नूडल्स कार्बोहाइड्रेट का मुख्य स्रोत हैं, और यह मान उन लोगों के लिए दिया गया है जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],[PP,"सामग्री की मात्रा और परोसे के आकार का पालन करने पर यह रेसिपी पोटैशियम में कम है। इसलिए यह उन लोगों के लिए उपयुक्त है जिन्हें अपने आहार में पोटैशियम घटाने की सलाह दी गई है। यह रेसिपी फ़ॉस्फ़ेट में भी कम है, हालाँकि इसमें कुछ फ़ॉस्फ़ेट होता है (मुख्य रूप से चिकन और मेवों से) इसलिए यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो निर्देशानुसार लें।"],[PR,"यह रेसिपी प्रोटीन का स्रोत है। कम प्रोटीन वाले विकल्प के लिए, चिकन को घटाकर 75g करने और चरण 6 में पानी निथारे हुए छोलों का एक छोटा डिब्बा (200g) मिलाने पर विचार करें।"],[TP,"तिल का तेल अधिक महँगा है, लेकिन अतिरिक्त कीमत के लायक है, क्योंकि थोड़ी मात्रा शानदार स्वाद जोड़ती है। कम नमक वाली सोया सॉस में भी नमक होता है, इसलिए सावधानी से मापें।"]],
[]))
R.append((3236439,"चेरी फ़ाइलो पेस्ट्री टार्ट","एक बेहतरीन मिठाई, जो सभी के लिए उपयुक्त है।","6",None,
["250g जमी हुई बीज रहित चेरी","75g दानेदार चीनी","1 छोटा चम्मच वनीला एसेंस","1 बड़ा चम्मच एरोरूट पाउडर","1 बड़ा चम्मच पानी","1 डिब्बा तैयार उपयोग वाली फ़ाइलो पेस्ट्री (लगभग 250g)","1 बड़ा चम्मच तेल","60g मक्खन","1 बड़ा चम्मच आइसिंग शुगर"],
["जमी हुई चेरी, चीनी और वनीला एसेंस को सॉसपैन में डालें। मध्यम आँच पर 5 मिनट बार-बार चलाते हुए पकाएँ। स्पैटुला से चेरी को धीरे से तोड़ें। एरोरूट पाउडर और पानी को मिलाकर पेस्ट बनाएँ।","पेस्ट को पकी हुई चेरी में चलाते हुए डालें। उबाल आने दें, फिर आँच से उतारें और ठंडा होने दें। ओवन को 190°C / 170°C फ़ैन / गैस मार्क 5 पर पहले से गरम करें और मफ़िन ट्रे पर चिकनाई लगाएँ।","पेस्ट्री की तीन शीट लें और हर एक को चार चौकोर टुकड़ों में काटें। मक्खन को पिघलाएँ और पेस्ट्री के दोनों ओर लगाएँ और छह खानों में दो-दो चौकोर टुकड़ों से परत बिछाएँ। हर एक में एक बड़ा चम्मच चेरी का भरावन डालें। फ़ाइलो पेस्ट्री के किनारों को चेरी के भरावन के ऊपर मोड़कर ढीले ढंग से बंद करें।","हर टार्ट पर और मक्खन लगाएँ। ओवन में 10-15 मिनट बेक करें, जब तक पेस्ट्री हर तरफ़ से हल्की सुनहरी भूरी न दिखे। ओवन से निकालें और ठंडा करने की रैक पर रखें। ठंडा होने पर ऊपर से पिसी चीनी छिड़कें। गरम या कमरे के तापमान पर परोसें।"],
[[CH,"जमी हुई चेरी और तैयार पेस्ट्री का उपयोग करने का मतलब है कि इन टार्ट को साल भर विशेष अवसरों के लिए बनाया जा सकता है।"],[CB,"इस व्यंजन में कार्बोहाइड्रेट के मुख्य स्रोत चेरी, चीनी और फ़ाइलो पेस्ट्री हैं। कार्बोहाइड्रेट मान उन लोगों के लिए दिया गया है जिन्हें इंसुलिन समायोजन का प्रशिक्षण मिला है।"],[PP,"इस रेसिपी में चेरी हैं जिनमें पोटैशियम अधिक होता है, लेकिन रेसिपी में बताई गई मात्रा में उपयोग करने पर यह कम पोटैशियम वाला व्यंजन बना रहता है।\nइस व्यंजन में थोड़ा फ़ॉस्फ़ेट होता है जो मुख्य रूप से फ़ाइलो पेस्ट्री से आता है। यदि आपको फ़ॉस्फ़ेट बाइंडर निर्धारित किया गया है, तो उन्हें इस व्यंजन के साथ लेना सुनिश्चित करें।"],[PR,"इस व्यंजन में प्रोटीन कम है और यदि आपको कम प्रोटीन वाला आहार लेने की सलाह दी गई है, तो यह किसी विशेष अवसर के लिए उपयुक्त मिठाई है।"],[GF,"ग्लूटेन-मुक्त तैयार फ़ाइलो पेस्ट्री ढूँढना कभी-कभी कठिन होता है, इसलिए आप इसके बजाय ग्लूटेन-मुक्त पफ़ पेस्ट्री का उपयोग करना चाह सकते हैं।"],[VG,"कई तैयार फ़ाइलो पेस्ट्री डेयरी-मुक्त होती हैं। मक्खन की जगह डेयरी-मुक्त स्प्रेड का उपयोग करें।"],[HO,"यदि आप चीनी या वसा की मात्रा कम करना चाहते हैं, तो चेरी के भरावन में उपयोग की गई चीनी की मात्रा घटाएँ, या उसे स्वीटनर से बदलें। मक्खन की जगह कम वसा वाले स्प्रेड का उपयोग करने पर विचार करें।"],[CO,"वनीला की फलियों के बजाय वनीला एक्सट्रैक्ट का उपयोग किया जा सकता है।"],[ST,"ठंडा होने के बाद, हवाबंद डिब्बे में फ्रिज में रखें और दो दिन के भीतर खा लें।"]],
[]))
